('81493dee-4b23-509d-b2bb-d68e25b37358'::uuid,'est2','"Solid Geometry & Volume"'::jsonb,'medium','mcq','"[Figure: Rectangular tank 4 m long, 2 m wide, partially filled with water to a depth of 3 m.]\nThe figure shows a rectangular tank partially filled with water. If the water level in the tank decreases by 0.6 of a meter, what is the volume of water remaining in the tank?"'::jsonb,'[{"key":"A","text":"4.3 cubic meters"},{"key":"B","text":"11.4 cubic meters"},{"key":"C","text":"14.4 cubic meters"},{"key":"D","text":"19.2 cubic meters"},{"key":"E","text":"28.8 cubic meters"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t7.md","source_sha256":"0fb6c459b96ac5b60a4c189de7328ebcb6d3bb964b72869331be58aa609b2ef5","source_question_id":"T7-41","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Solid Geometry & Volume"}'::jsonb,'"D"'::jsonb,'"Source-keyed answer from book_t7.md (T7-41)."'::jsonb),
