('13487faa-39ef-5438-a388-c8aaa0c36a4f'::uuid,'est2','"Rational, Radical, Exponential & Logarithmic Functions"'::jsonb,'medium','mcq','"[Figure: Decreasing exponential curve through (0, 6), approaching y = 0 as x increases.]\nAn exponential function is graphed on the grid. Which function is best represented by the graph?"'::jsonb,'[{"key":"A","text":"g(x) = 6(1/3)ˣ"},{"key":"B","text":"g(x) = 6(3)ˣ"},{"key":"C","text":"g(x) = 6 − (1/3)ˣ"},{"key":"D","text":"g(x) = 6 − (3)ˣ"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t8.md","source_sha256":"8f03df34fa98881a0531e925df7d2a108b1590182b68af8e273abe0930b44cfb","source_question_id":"T8-09","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Rational, Radical, Exponential & Logarithmic Functions"}'::jsonb,'"A"'::jsonb,'"Source-keyed answer from book_t8.md (T8-09)."'::jsonb),
