('8bf1f541-c7e5-52b6-adeb-2d0e450decd9'::uuid,'est2','"Algebra Foundations, Equations & Inequalities"'::jsonb,'medium','mcq','"A college student completed some courses worth 3 credits and some courses worth 4 credits. The student earned a total of 59 credits after completing 18 courses. How many courses worth 3 credits did the student complete?"'::jsonb,'[{"key":"A","text":"13"},{"key":"B","text":"5"},{"key":"C","text":"20"},{"key":"D","text":"39"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t8.md","source_sha256":"8f03df34fa98881a0531e925df7d2a108b1590182b68af8e273abe0930b44cfb","source_question_id":"T8-25","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Algebra Foundations, Equations & Inequalities"}'::jsonb,'"A"'::jsonb,'"Source-keyed answer from book_t8.md (T8-25)."'::jsonb),
